import{_ as a}from"./chunks/library-overview.Bu864uIA.js";import{_ as t}from"./chunks/volume-settings.DLnHK18N.js";import{_ as o,o as s,c as n,a2 as r}from"./chunks/framework.Dx-TCpNt.js";const f=JSON.parse('{"title":"Library & Import","description":"The library is built by scanning raw/ every time the app loads. No database, no import step that copies your scans: the folder tree is the configuration.","frontmatter":{"description":"The library is built by scanning raw/ every time the app loads. No database, no import step that copies your scans: the folder tree is the configuration."},"headers":[],"relativePath":"guide/gallery.md","filePath":"guide/gallery.md","lastUpdated":1794830541000}'),i={name:"guide/gallery.md"};function l(d,e,h,p,c,g){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="library-import" tabindex="-1">Library &amp; Import <a class="header-anchor" href="#library-import" aria-label="Permalink to &quot;Library &amp; Import&quot;">​</a></h1><p>The library is built by scanning <code>raw/</code> every time the app loads. No database, no import step that copies your scans: <strong>the folder tree is the configuration</strong>.</p><p>This page covers how to lay out files, how the scanner pairs languages, how to link a folder that lives somewhere else, and which import door leads where.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Scans arrive in whatever shape the previous owner left them: <code>Vol.14/Japanese/ch01</code>, <code>点兔第14卷/ja/172</code>, <code>manga/zh-cn/172</code>. You want one shelf that lists volumes and chapters, lines page 1 of every language up with page 1 of the others, and tells you where a file is missing — without renaming or moving anything first.</p><h2 id="directory-shape" tabindex="-1">Directory shape <a class="header-anchor" href="#directory-shape" aria-label="Permalink to &quot;Directory shape&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/</span></span>
<span class="line"><span>  &lt;volume&gt;/</span></span>
<span class="line"><span>    &lt;language-dir&gt;/</span></span>
<span class="line"><span>      &lt;chapter&gt;/</span></span>
<span class="line"><span>        001.jpg</span></span>
<span class="line"><span>        002.jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>One <code>raw/</code> can also hold several works side by side, each with its own volumes:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/</span></span>
<span class="line"><span>  &lt;work&gt;/</span></span>
<span class="line"><span>    &lt;volume&gt;/</span></span>
<span class="line"><span>      &lt;language-dir&gt;/</span></span>
<span class="line"><span>        &lt;chapter&gt;/</span></span>
<span class="line"><span>          001.jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li>A <strong>volume</strong> is a top-level folder under <code>raw/</code> by default. When several works sit side by side, the volume is the folder inside a work folder, and the work name is shown as the series (the sidebar writes &quot;series · volume&quot;). Both layouts can coexist: the scanner tries the flat volume rule first and falls back to the series rule. See <a href="/KomaYomi-docs/guide/folder-rules#a-root-holding-several-works">directory rules</a>.</li><li>A <strong>chapter</strong> is any folder inside a language directory. Chapters are unioned across languages, so one edition may skip a chapter folder entirely.</li><li><strong>Pages pair by sorted position, not by filename.</strong> Each language sorts naturally (digit runs compared as numbers), then pairs by index. <code>1.jpg</code>, <code>2.jpg</code>, <code>10.jpg</code> come out in the right order.</li></ul><figure class="shot"><img src="`+a+`" alt="Library sidebar with volumes, chapters and language badges"><figcaption>The sidebar lists volume → chapter → pages. Language badges show which editions exist for a volume; warnings appear inline.</figcaption></figure><h2 id="page-list-layouts" tabindex="-1">Page list layouts <a class="header-anchor" href="#page-list-layouts" aria-label="Permalink to &quot;Page list layouts&quot;">​</a></h2><p>The three buttons at the top of the sidebar choose how pages are listed inside a chapter:</p><ul><li><strong>Two-column thumbnails</strong> (default) — a grid of cover-sized thumbnails.</li><li><strong>Single-column thumbnails</strong> — one larger thumbnail per row.</li><li><strong>List</strong> — one compact row per page, showing the page number, the languages present (missing ones are dimmed with a tooltip), a <code>!</code> when the page has warnings, and <code>✎ n</code> for the page&#39;s note count.</li></ul><p>The choice applies to every volume and chapter, survives reloads, and is stored per browser in <code>localStorage</code> under <code>manga-memo.page-list-layout</code>; it is not written to <code>data/</code>, so another browser or machine keeps its own setting. Switching layouts keeps the current scroll position.</p><h2 id="language-directory-names" tabindex="-1">Language directory names <a class="header-anchor" href="#language-directory-names" aria-label="Permalink to &quot;Language directory names&quot;">​</a></h2><p>The scanner normalizes a folder name (lowercase, spaces and underscores to hyphens) and matches it against aliases:</p><table tabindex="0"><thead><tr><th>Language</th><th>Accepted directory names</th></tr></thead><tbody><tr><td>Japanese (<code>ja</code>)</td><td><code>ja</code>, <code>jp</code>, <code>jpn</code>, <code>japanese</code>, <code>ja-jp</code>, <code>日</code>, <code>日本語</code>, <code>日文</code></td></tr><tr><td>Chinese (<code>zh</code>)</td><td><code>zh</code>, <code>zh-cn</code>, <code>zh-hans</code>, <code>zh-sg</code>, <code>cn</code>, <code>chs</code>, <code>zh-tw</code>, <code>zh-hk</code>, <code>zh-hant</code>, <code>cht</code>, <code>tw</code>, <code>hk</code>, <code>中</code>, <code>中文</code>, <code>繁中</code>, <code>简中</code></td></tr><tr><td>English (<code>en</code>)</td><td><code>en</code>, <code>en-us</code>, <code>en-gb</code>, <code>us</code>, <code>uk</code>, <code>eng</code>, <code>english</code>, <code>英</code>, <code>英文</code></td></tr></tbody></table><p>If a folder name is not recognized, the volume still appears, wearing a warning. Open <strong>volume settings</strong> (the gear on the volume row) to pin a directory to a language. The choice is stored in <code>data/library.json</code>:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;volumes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;点兔第14卷&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;dirs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>A volume can carry as many languages as you can map; the three built-ins are just the usual suspects. The compare reader only offers languages that actually exist for the current page.</p><h2 id="volume-settings" tabindex="-1">Volume settings <a class="header-anchor" href="#volume-settings" aria-label="Permalink to &quot;Volume settings&quot;">​</a></h2><p>Volume settings is the repair bay for a volume whose folders did not introduce themselves properly. Open it with the gear on the volume row.</p><ol><li>The dialog lists a dropdown for each language detected on the volume, plus <strong>Japanese</strong>, <strong>中文</strong> and <strong>English</strong> as defaults.</li><li>Choose the subfolder that holds each language. <strong>Not used / auto</strong> hands the folder back to auto-detection.</li><li>Click <strong>Save</strong>. The library rescans and the volume&#39;s language badges update.</li><li><strong>Remove from library</strong> deletes only the link under <code>raw/</code>; the images in the original folder and the annotations under <code>data/pages/</code> survive.</li></ol><p>A folder can belong to only one language; folders already taken disappear from the other dropdowns. If no language folder was detected at all, the dialog says so and repeats the volume warnings that explain why.</p><p>The same dialog has a <strong>Chapters</strong> section listing every chapter of the volume:</p><ul><li><strong>Remove</strong> next to a chapter only unlinks it from the library. The chapter folder, images, notes and annotations stay on disk; removed chapters appear under <strong>Removed chapters</strong>, where <strong>Restore</strong> brings them back.</li><li><strong>Page offset</strong> handles pages inserted mid-chapter that shift every later page number: align this language from page N to page M of the reference edition, or leave it empty for no offset. Offsets are stored as <code>pageOffsets</code> in <code>data/library.json</code>; they affect display and pairing only, never file names on disk.</li></ul><figure class="shot"><img src="`+t+'" alt="Volume settings dialog with one dropdown per language: ja, zh and en, plus Remove from library, Cancel and Save"><figcaption>Volume settings. Each dropdown maps a language to its subfolder; Save rescans the volume, and Remove from library only deletes the link under raw/.</figcaption></figure><div class="tip custom-block"><p class="custom-block-title">Fix the mapping before annotating</p><p>Panels and notes are stored per volume and chapter. If the mapping changes later, the page data can no longer be found. Set the mapping, open a few pages, and only then start correcting panels.</p></div><h2 id="adding-a-folder-that-lives-elsewhere" tabindex="-1">Adding a folder that lives elsewhere <a class="header-anchor" href="#adding-a-folder-that-lives-elsewhere" aria-label="Permalink to &quot;Adding a folder that lives elsewhere&quot;">​</a></h2><p><strong>＋ Add manga</strong> has two modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What happens</th></tr></thead><tbody><tr><td>Leave the path blank</td><td>Creates an empty folder under <code>raw/</code>.</td></tr><tr><td>Pick an existing folder</td><td>Creates a <strong>folder link</strong> under <code>raw/</code> that points at the original. Images are not copied, and annotations remain writable because the link behaves like a normal folder.</td></tr></tbody></table><p>Optional: give the volume a different display name. The hint under the field shows the expected layout: <code>language/chapter/page.jpg</code>.</p><p>If the folder you pick is itself a work or a series (volumes laid out as <code>work/volume/language/chapter/images</code>), the tool links every volume under the <code>raw/</code> root and records the work name in the <code>series</code> field of <code>data/library.json</code>. The sidebar then shows &quot;series · volume&quot;, and volumes that share a name across works stay separate (their ids get the work name as a prefix).</p><p><strong>Remove from library</strong> (in volume settings) deletes only the link under <code>raw/</code>; images in the original folder are untouched, and annotations already saved under <code>data/pages/</code> are kept.</p><p>In a plain browser there is no folder picker. Type the absolute path instead, or use the desktop build and click <strong>Choose a folder…</strong>.</p><h2 id="page-and-language-roles" tabindex="-1">Page and language roles <a class="header-anchor" href="#page-and-language-roles" aria-label="Permalink to &quot;Page and language roles&quot;">​</a></h2><p>Three different &quot;roles&quot; are easy to confuse:</p><table tabindex="0"><thead><tr><th>Role</th><th>Where it is chosen</th><th>What it affects</th></tr></thead><tbody><tr><td><strong>Base image</strong></td><td>Panel workbench toolbar</td><td>Which language&#39;s artwork you draw panels on. Panel rectangles are shared by all languages on that page.</td></tr><tr><td><strong>Compare languages</strong></td><td>Compare reader language chips</td><td>Which languages are displayed, in which order. Not every language has to be enabled.</td></tr><tr><td><strong>Primary language</strong></td><td>PNG export</td><td>Whole-page and current-panel PNG use the base language; the trilingual collage uses the selected compare languages.</td></tr></tbody></table><p>Panels and notes are stored once per page, not once per language. Alignment offsets are stored per language and, optionally, per panel.</p><h2 id="warnings-you-will-see" tabindex="-1">Warnings you will see <a class="header-anchor" href="#warnings-you-will-see" aria-label="Permalink to &quot;Warnings you will see&quot;">​</a></h2><p>Library warnings are gossip, not errors: the page still opens.</p><table tabindex="0"><thead><tr><th>Warning</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><em>No language directory recognized</em></td><td>None of the subfolders matched an alias.</td><td>Map them in volume settings or rename them.</td></tr><tr><td><em>Unrecognized directory: …</em></td><td>Extra folders sit next to language folders.</td><td>Map them, or ignore them.</td></tr><tr><td><em>Page counts differ across languages</em></td><td>Languages have different numbers of files.</td><td>Pairing is by index; add or remove the missing page.</td></tr><tr><td><em>Mixed extensions in this chapter</em></td><td>e.g. <code>.jpg</code> and <code>.png</code> alternate.</td><td>Usually harmless; normalize if you care about consistent thumbnails.</td></tr><tr><td><em>Filename does not match page number</em></td><td>The leading number in the filename differs from its sorted position.</td><td>Rename if the mismatch indicates a missing or extra page.</td></tr></tbody></table><h2 id="folder-rules-for-unusual-layouts" tabindex="-1">Folder rules for unusual layouts <a class="header-anchor" href="#folder-rules-for-unusual-layouts" aria-label="Permalink to &quot;Folder rules for unusual layouts&quot;">​</a></h2><p>The default shape covers most libraries: the flat <code>volume/language/chapter</code> layout and a root holding several works as <code>work/volume/language/chapter/images</code> are both recognised out of the box. If your folders put the language last, have no language folder at all, or skip the chapter level, open <strong>Folder rules…</strong> and describe the path with placeholders. Rules are tried in order and the first match wins; they only affect detection and never rename or move files.</p><p>The full syntax, rule fields and preview workflow are on <a href="/KomaYomi-docs/guide/folder-rules">Folder Detection Rules</a>.</p><h2 id="import-exchange-and-restore" tabindex="-1">Import, exchange and restore <a class="header-anchor" href="#import-exchange-and-restore" aria-label="Permalink to &quot;Import, exchange and restore&quot;">​</a></h2><p>Four different entry points live in the sidebar. They do different things:</p><table tabindex="0"><thead><tr><th>Entry</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Add manga</strong></td><td>Link an existing image folder into the library.</td></tr><tr><td><strong>Project file…</strong></td><td>Export or import a <code>.mnproj</code> package (images + annotations + templates + language settings).</td></tr><tr><td><strong>Exchange files…</strong></td><td>Move <code>.mntpl</code> layout templates, <code>.mnexp</code> export templates or a single <code>.mnpage.json</code> page.</td></tr><tr><td><strong>Backup / restore</strong></td><td>ZIP the <code>data/</code> folder, or restore a previous ZIP.</td></tr></tbody></table><p>Imports are validated first and the original files are backed up under <code>data/backups/</code>. See <a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> for the file contents and version rules.</p><div class="tip custom-block"><p class="custom-block-title">Import order</p><p>Restore a <strong>backup</strong> when you want your annotations back on the same machine. Import a <strong>project</strong> when you move to another machine. Use <strong>exchange files</strong> when you only want to share a layout, an export style or one page.</p></div><h2 id="navigation-and-performance" tabindex="-1">Navigation and performance <a class="header-anchor" href="#navigation-and-performance" aria-label="Permalink to &quot;Navigation and performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Previous / next page</td><td><code>[</code> / <code>]</code></td></tr><tr><td>Panel workbench</td><td><code>P</code></td></tr><tr><td>Compare reader</td><td><code>C</code></td></tr><tr><td>Toggle sidebar</td><td><code>S</code></td></tr><tr><td>Toggle notes panel</td><td><code>N</code></td></tr><tr><td>Open export dialog</td><td><code>E</code></td></tr><tr><td>Help</td><td><code>?</code></td></tr></tbody></table><p>The URL hash is deep-linkable: <code>#/&lt;volume&gt;/&lt;chapter&gt;/&lt;page&gt;/&lt;panels|compare|original&gt;</code>. Double-click a panel in the compare reader to open its detail view; the URL then gains a <code>/panel/&lt;panelId&gt;</code> segment (for example <code>#/vol-01/01/3/compare/panel/p-2</code>), so refreshing or sharing the link restores the same page and panel.</p><p>In the detail view:</p><ul><li>Every enabled language is shown side by side (stacked vertically on phones and tablets), followed by this panel&#39;s notes and annotations.</li><li>Zoom runs from 100% to 600% with the toolbar buttons, the wheel or a pinch; zooming and panning affect the enlarged images only.</li><li>The middle arrows switch to the previous / next panel, and the outer arrows turn pages. Arrow keys switch panels instead of pages while the view is open.</li><li><code>Esc</code>, the close button or the browser Back button leaves the view and returns to the same page and panel position. A link opened from someone else rewrites the URL instead of adding a history entry.</li></ul><p>Thumbnails are generated on demand and cached in <code>data/cache/thumbs/</code>. Deleting that folder is safe; thumbnails are rebuilt on the next visit. The image format is sniffed from the file header, so a <code>.png</code> that is really a JPEG still renders correctly.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Renaming a file changes its page position.</strong> Pairing is by sorted index; inserting a page shifts every page after it. Add the new page at the end, or rename the whole chapter consistently. See <a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a>.</li><li><strong>One missing language is not an error.</strong> The page opens, and the compare reader shows a placeholder for the missing language.</li><li><strong>A folder link is not a copy.</strong> If you move or delete the original folder, the library breaks. Re-add the folder after moving it.</li><li><strong>AVIF, HEIC, GIF and BMP are displayed but not decoded for detection.</strong> WebP is decoded. Use JPEG or PNG when you rely on automatic splitting (see <a href="/KomaYomi-docs/guide/panels">Panel Workbench</a>).</li><li><strong>The sidebar is the truth.</strong> If a volume or chapter is missing, check the folder name casing and the language aliases before anything else.</li><li><strong>A language dropdown does not offer the folder.</strong> It is already assigned to another language in volume settings.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a> — clean up scans before importing.</li><li><a href="/KomaYomi-docs/guide/folder-rules">Folder Detection Rules</a> — non-standard directory layouts.</li><li><a href="/KomaYomi-docs/guide/panels">Panel Workbench</a> — what to do after a page opens.</li><li><a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> — what a <code>.mnproj</code> contains.</li><li><a href="/KomaYomi-docs/guide/remote">Remote Storage &amp; Backup</a> — keeping images on a NAS or WebDAV.</li></ul>',61)])])}const y=o(i,[["render",l]]);export{f as __pageData,y as default};
